-- SQL SCRIPT FOR IMPORTING EXCEL COMMODITY FARMGATE PRICES (2026 WEEKLY DATES) INTO SUPABASE

-- 1. INSERT INTO market_farmgate_prices
ON CONFLICT (id) DO UPDATE SET
  farmgate_price = EXCLUDED.farmgate_price,
  market_price = EXCLUDED.market_price;

-- 2. INSERT INTO historical_records
ON CONFLICT (id) DO UPDATE SET
  price_per_kg = EXCLUDED.price_per_kg;
